import{marked,Renderer}from"marked";import hljs from"highlight.js";const renderer=new Renderer;renderer.code=({text:e,lang:r})=>{r=(r=r||"").toLowerCase();const n=hljs.getLanguage(r)?r:"plaintext";return`<pre><code class="hljs language-${n}">${hljs.highlight(e,{language:n}).value}</code></pre>`},marked.use({renderer:renderer});export async function markedParse(e){return marked(e)}